import React, { useEffect, useState } from 'react';
import './DisplayFoodTruck.css';

function DisplayFoodTruck() {
  const [vendors, setVendors] = useState([]);

  useEffect(() => {
    fetch('http://localhost:8080/getAllVendors')
      .then(res => res.json())
      .then(data => setVendors(data))
      .catch(err => console.error("Error fetching vendors:", err));
  }, []);

  return (
    <div className="vendor-container">
      <h2>Food Truck Vendors</h2>
      {vendors.length === 0 ? (
        <p>No vendors available.</p>
      ) : (
        <ul className="vendor-list">
          {vendors.map((vendor, index) => (
            <li key={index} className="vendor-card">
              <h3>{vendor.vendorName}</h3>
              <p><strong>Cuisine:</strong> {vendor.cuisineType}</p>
              <p><strong>Region:</strong> {vendor.operatingRegion}</p>
              <p><strong>Highlights:</strong> {vendor.highlights}</p>
              <p><strong>Phone:</strong> {vendor.phoneNumber}</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default DisplayFoodTruck;
